 origin:[
  [Z("01 · Agent 会变，安全结论却常被当成静态的","01 · Agents change while safety claims are often static"),Z("Persistent Agent 会持续写 memory、更新 workflow；今天通过测试，并不代表未来仍处在同一状态。","Persistent agents keep changing memory and workflows; a pass today does not describe tomorrow's state.")],
  [Z("02 · 最早看起来像‘更新后更危险’","02 · The first result looked like update risk"),Z("单看 HarmBench，updated / base / NullMemory 的未来事件数量有明显方向，很容易被写成 update-associated risk。","Under HarmBench alone, updated/base/NullMemory showed a clear ordering that looked like update-associated risk.")],
  [Z("03 · 第二个 evaluator 把故事翻了过来","03 · A second evaluator reversed the story"),Z("同样 trajectories 交给冻结 DeepSeek 后，current premise 和三臂 future ordering 都变化。","On the same trajectories, frozen DeepSeek changed both the current premise and future three-arm ordering.")],
  [Z("04 · 真正问题变成‘这个安全结论稳定吗？’","04 · The real question became whether the conclusion is stable"),Z("论文从‘更新是否危险’转成 measurement identification：结论是否能跨独立评价器成立。","The paper moved from update risk to measurement identification: does the conclusion survive independent evaluators?")]
 ],
 gapLead:Z("现有安全评估通常默认一个 judge 给出的标签足够稳定；G1 研究的正是这个默认前提什么时候不成立。","Safety evaluation often assumes one judge is stable enough; G1 studies when that assumption fails."),
 gaps:[
  [Z("静态安全测试","Static safety tests"),Z("能告诉我们当前快照是否通过。","Tell us whether the current snapshot passes."),Z("但 persistent Agent 的未来状态会继续变化。","But persistent agents keep changing.")],
  [Z("单一自动评价器","One automated evaluator"),Z("给出清晰、可批量的标签。","Provides scalable labels."),Z("却可能把 evaluator-specific measurement 当成系统固有属性。","Can mistake evaluator-specific measurement for a system property.")],
  [Z("投票 / 事后加权","Voting / post-hoc weighting"),Z("可以把多个 judge 压成一个数字。","Compresses multiple judges into one number."),Z("会掩盖‘换 evaluator 会翻方向’这个最重要的事实。","Can hide the fact that changing evaluators reverses the direction.")]
 ],
 work:[
  [Z("固定被测对象","Freeze the object"),Z("同一批 trajectories","Same trajectories"),Z("状态、任务和轨迹保持不变，只更换 independently frozen evaluator。","Hold states, tasks, and trajectories fixed; change only the frozen evaluator.")],
  [Z("保留分歧","Keep disagreement"),Z("不投票抹平","Do not vote it away"),Z("两个 evaluator 的 label vector 都保留，不事后指定 ground truth。","Keep both label vectors instead of choosing a ground truth after seeing results.")],
  [Z("把不确定变成可计算对象","Turn uncertainty into an object"),Z("ERTA sets / envelope","ERTA sets / envelope"),Z("用 definite / possible event set 和 contrast envelope 判断什么能确定。","Use definite/possible event sets and contrast envelopes to separate identified from unidentified conclusions.")],
  [Z("防止事后包装","Prevent post-hoc rules"),Z("Prospective PV1","Prospective PV1"),Z("在 fresh outcomes 前冻结 tasks、evaluators 和 verdict rule，检查协议能否真的 fail closed。","Freeze tasks, evaluators, and verdict rule before fresh outcomes to test prospective fail-closed behavior.")]
 ],
 chain:[Z("同一 Agent 轨迹","Same trajectories"),Z("两个独立评价器","Two evaluators"),Z("事件集合 / 排序不同","Different events / ordering"),Z("输出可确定范围","Report identified range")],
 rqs:[
  ["RQ1",Z("连‘当前是安全的’这个前提稳定吗？","Is even the current-safe premise stable?"),Z("同一 12 条 current trajectories 分别由 HarmBench 和 DeepSeek 判定。","Label the same 12 current trajectories with HarmBench and DeepSeek."),Z("不完全稳定：HB 0/12，DS 1/12。","Not fully: HB is 0/12 while DS is 1/12.")],
  ["RQ2",Z("未来哪个条件更危险，方向稳定吗？","Is the future three-arm direction stable?"),Z("比较 updated / base / NullMemory 的 future event counts。","Compare future event counts for updated/base/NullMemory."),Z("不稳定：HB 8/4/0，DS 5/5/8，排序直接翻转。","No: HB is 8/4/0 while DS is 5/5/8, reversing the ordering.")],
  ["RQ3",Z("这种分歧能在新数据上被协议正确识别吗？","Can the protocol recognize this prospectively?"),Z("在新 labels 前冻结 PV1 的 12 episodes、两个 evaluator 和判定规则。","Freeze 12 PV1 episodes, two evaluators, and the verdict rule before new labels."),Z("可以：PV1 得到 HB 0/12、DS 3/12，ERTA 按预注册规则输出 measurement-inconclusive。","Yes: PV1 gives HB 0/12 and DS 3/12, and ERTA returns measurement-inconclusive as preregistered.")]
 ],
 evidence:[["0/12 vs 1/12",Z("连 current-safe premise 都出现 evaluator disagreement。","The current-safe premise already disagrees.")],["8/4/0 vs 5/5/8",Z("同一批未来轨迹的三臂排序随 evaluator 翻转。","The three-arm future ordering reverses across evaluators.")],["PV1 · 0/12 vs 3/12",Z("fresh panel 仍然分歧，冻结协议没有强行给方向。","A fresh panel still disagrees, and the frozen protocol refuses a directional claim.")]],
 contributions:[["C1",Z("把时间安全改写成测量稳定性问题","Reframe temporal safety as measurement stability"),Z("persistent setting 下必须检查结论是否跨评价器稳定。","Persistent settings require checking evaluator stability.")],["C2",Z("用 partial identification 保留可确定部分","Preserve what is identifiable"),Z("ERTA 不投票，而是报告 definite / possible sets 与 contrast envelope。","ERTA reports definite/possible sets and contrast envelopes rather than voting.")],["C3",Z("用 prospective panel 验证 fail-closed","Prospectively validate fail-closed behavior"),Z("PV1 在结果前冻结规则，证明新 disagreement 出现时协议会真的停止升级结论。","PV1 freezes rules before outcomes and demonstrates real fail-closed operation.")]],
 limits:[Z("HarmBench、DeepSeek、majority vote 都不被当成人类语义真值。","HarmBench, DeepSeek, and majority vote are not human semantic ground truth."),Z("PV1 只有 12 episodes、一个 Qwen3-8B backbone，不能证明广泛泛化。","PV1 has 12 episodes and one Qwen3-8B backbone; it does not establish broad generalization."),Z("当前标签主要是 trace/action-attempt measurement，不等于真实 external harmful completion。","Current labels mainly capture trace/action-attempt semantics, not external harmful completion."),Z("独立 human semantic labels 仍是最重要的外部证据缺口。","Independent human semantic labels remain the key missing anchor.")],
 statusHeadline:Z("科学现象已经很清楚，但论文还缺一个独立的人类语义锚点","The measurement issue is clear, but the paper still lacks an independent human semantic anchor"),
 statusCards:[[Z("当前科学状态","SCIENTIFIC STATE"),"READY",Z("双评价器 reversal 与 prospective PV1 已完成。","Dual-evaluator reversal and prospective PV1 are complete.")],[Z("论文准备状态","PAPER READINESS"),"PREBUTTAL",Z("下一步不是堆更多 automated judge，而是补盲化 human semantic labels。","The next need is blinded human semantic labels, not more automated judges.")]],
 nextPlain:Z("补齐盲化人类语义标签，然后严格按冻结规则重跑 paper-readiness；不因为某个 evaluator 更符合预期就事后改权重。","Acquire blinded human labels and rerun frozen readiness checks; do not reweight evaluators after seeing which result is preferred."),
